#tabmail-arrowscrollbox {
  min-block-size: var(--tab-min-height);

  &::part(scrollbox) {
    contain: inline-size;
  }

  &::part(scrollbutton-up),
  &::part(scrollbutton-down) {
    fill: var(--toolbarbutton-icon-fill, currentColor);
    fill-opacity: var(--toolbarbutton-icon-fill-opacity);
  }
